output_text:
[
  {
    "id": "entry_cart_checkout",
    "text": "A shopper should check out the entrance cart before doing the trip through the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "checkout_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items should be picked up only while the shopper has the cart, not while walking without it.",
    "abstraction": {
      "state_properties": {
        "shopper_has_cart": "hasCart",
        "shopper_without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "shopper_without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper should not carry merchandise by hand when the cart system is available.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "become_hand_loaded": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "A shopper may put the cart down only at the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper should not leave the supermarket while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "shopper_has_cart": "hasCart"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "EXIT",
              "shopper_has_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "cart_return_final_interaction",
    "text": "Once the cart has been returned, the shopper should not do any further store interactions and should simply proceed to the exit.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_parked_in_return_bay",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "cart_free_exit_zone",
    "text": "Carts are prohibited in the pedestrian checkout and exit zone on the east side of the store.",
    "abstraction": {
      "state_properties": {
        "pedestrian_exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_pedestrian_exit_zone": {
          "and": [
            "hasCart",
            "pedestrian_exit_zone"
          ]
        }
      },
      "events": {
        "move_cart_into_exit_zone": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "pedestrian_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_pedestrian_exit_zone"
    }
  }
]
